package com.fixit.dto; import jakarta.validation.constraints.*; import lombok.*;
@Data @NoArgsConstructor @AllArgsConstructor @Builder public class ProductEnquiryRequest { @NotBlank(message="Product ID is required") private String productId; @NotBlank(message="Customer name is required") @Size(min=2,max=255,message="Name must be between 2 and 255 characters") private String customerName; @NotBlank(message="Phone number is required") @Pattern(regexp="^\\+?[0-9]{10,15}$",message="Invalid phone number format") private String customerPhone; @NotBlank(message="Email is required") @Email(message="Invalid email format") private String customerEmail; }
